describe('Comment on a record', () => {
    const recordId = '12345'; // Example record ID
    const commentText = 'This is a test comment.';
    const emptyCommentText = '';

    beforeEach(() => {
        cy.visit(`/records/${recordId}`);
    });

    it('should allow the user to add a comment to a record', () => {
        cy.get('textarea[name="comment"]').type(commentText);
        cy.get('button[type="submit"]').click();

        cy.get('.comments-list').should('contain', commentText);
        cy.get('textarea[name="comment"]').should('be.empty');
    });

    it('should not allow the user to submit an empty comment', () => {
        cy.get('textarea[name="comment"]').type(emptyCommentText);
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('contain', 'Comment cannot be empty');
        cy.get('.comments-list').should('not.contain', emptyCommentText);
    });
});
